<script setup lang="ts">
import {ref,computed,onMounted,onBeforeUnmount} from 'vue'
import {api,body,list,date,type Row} from '../api'
import SelectField from './SelectField.vue'
import Icon from './Icon.vue'
import {confirmAction} from '../confirm'
import '../series.css'
const items=ref<Row[]>([]),selected=ref<Row|null>(null),chapters=ref<Row[]>([]),loading=ref(true),busy=ref(false),error=ref(''),message=ref(''),query=ref(''),next=ref(''),more=ref(false),baseline=ref('')
const candidates=ref<Row[]>([]),postQuery=ref(''),postNext=ref(''),postMore=ref(false),postLoading=ref(false),picker=ref(false)
let listVersion=0,detailVersion=0,postVersion=0
const payload=()=>selected.value?{title:selected.value.title,slug:selected.value.slug||'',description:selected.value.description||'',cover_media_id:selected.value.cover_media_id||null,status:selected.value.status,state:selected.value.state,chapter_post_ids:chapters.value.map(c=>String(c.post_id||c.id))}:null
const dirty=computed(()=>!!selected.value&&JSON.stringify(payload())!==baseline.value)
const selectedIDs=computed(()=>new Set(chapters.value.map(c=>String(c.post_id||c.id))))
const deletedChapters=computed(()=>chapters.value.filter(chapter=>chapter.status==='deleted').length)
const stateOptions=[{value:'ongoing',label:'连载中'},{value:'completed',label:'已完结'}],visibilityOptions=[{value:'draft',label:'草稿 · 仅自己可见'},{value:'published',label:'公开 · 进入专栏列表'}]
function report(e:unknown){error.value=e instanceof Error?e.message:'操作失败，请稍后重试'}
async function load(append=false){const generation=++listVersion;loading.value=true;error.value='';try{const q=new URLSearchParams({limit:'20',q:query.value});if(append&&next.value)q.set('cursor',next.value);const data=await api('/me/series?'+q);if(generation!==listVersion)return;items.value=append?[...items.value,...list(data)]:list(data);next.value=data.next_cursor||'';more.value=!!data.has_more}catch(e){if(generation===listVersion)report(e)}finally{if(generation===listVersion)loading.value=false}}
async function mayLeave(){return !dirty.value||await confirmAction('放弃未保存的专栏修改？','章节顺序和资料尚未保存。','放弃修改')}
function assign(data:Row){selected.value={...data};chapters.value=(data.chapters||[]).map((c:Row)=>({...c}));baseline.value=JSON.stringify(payload());candidates.value=[];picker.value=false;message.value=''}
async function open(row:Row){if(busy.value||!await mayLeave())return;const generation=++detailVersion;busy.value=true;error.value='';try{const data=await api('/studio/series/'+row.id);if(generation===detailVersion)assign(data)}catch(e){if(generation===detailVersion)report(e)}finally{if(generation===detailVersion)busy.value=false}}
async function back(){if(busy.value||!await mayLeave())return;selected.value=null;chapters.value=[];error.value='';message.value=''}
async function create(){if(busy.value||!await mayLeave())return;detailVersion++;assign({title:'',slug:'',description:'',cover_media_id:null,status:'draft',state:'ongoing',chapters:[]});error.value=''}
async function save(){if(!selected.value||busy.value)return;busy.value=true;error.value='';message.value='';try{const id=selected.value.id,data=await api(id?'/studio/series/'+id:'/series',{method:id?'PUT':'POST',version:id?selected.value.version:undefined,body:body(payload())});assign(data);message.value='专栏和章节顺序已保存';await load()}catch(e){report(e)}finally{busy.value=false}}
async function remove(){if(!selected.value?.id||busy.value)return;if(!await confirmAction('删除这个专栏？','只删除专栏及章节引用，文章正文仍然保留。','删除专栏'))return;busy.value=true;error.value='';try{await api('/studio/series/'+selected.value.id,{method:'DELETE',version:selected.value.version});selected.value=null;chapters.value=[];message.value='专栏已删除，文章仍然保留';await load()}catch(e){report(e)}finally{busy.value=false}}
async function findPosts(append=false){const generation=++postVersion;postLoading.value=true;error.value='';try{const q=new URLSearchParams({limit:'20',q:postQuery.value});if(append&&postNext.value)q.set('cursor',postNext.value);const data=await api('/me/posts?'+q);if(generation!==postVersion)return;const rows=list(data).filter(p=>p.status!=='deleted'&&p.status!=='trashed');candidates.value=append?[...candidates.value,...rows]:rows;postNext.value=data.next_cursor||'';postMore.value=!!data.has_more}catch(e){if(generation===postVersion)report(e)}finally{if(generation===postVersion)postLoading.value=false}}
function showPicker(){picker.value=!picker.value;if(picker.value&&!candidates.value.length)void findPosts()}
function add(post:Row){const id=String(post.id);if(selectedIDs.value.has(id)||chapters.value.length>=300)return;chapters.value.push({id,post_id:id,title:post.title,status:post.status})}
function move(index:number,delta:number){const target=index+delta;if(target<0||target>=chapters.value.length)return;const copy=[...chapters.value];[copy[index],copy[target]]=[copy[target]!,copy[index]!];chapters.value=copy}
async function upload(event:Event){const input=event.target as HTMLInputElement,file=input.files?.[0];if(!file||!selected.value||busy.value)return;busy.value=true;error.value='';try{const data=new FormData();data.append('file',file);const value=await api('/media',{method:'POST',body:data});selected.value.cover_media_id=value.media_id;selected.value.cover_url='/media/'+value.media_id;message.value='封面已上传，保存专栏后生效'}catch(e){report(e)}finally{busy.value=false;input.value=''}}
function beforeUnload(event:BeforeUnloadEvent){if(dirty.value){event.preventDefault();event.returnValue=''}}
onMounted(()=>{void load();addEventListener('beforeunload',beforeUnload)})
onBeforeUnmount(()=>{listVersion++;detailVersion++;postVersion++;removeEventListener('beforeunload',beforeUnload)})
</script>
<template>
 <section class="series-manager" :class="{'has-selection':!!selected}" aria-label="专栏管理">
  <p v-if="error" class="notice error" role="alert">{{error}}</p><p v-if="message" class="notice" role="status">{{message}}</p>
  <div class="series-manager-grid">
   <section class="series-index" aria-labelledby="my-series-title"><div class="series-panel-head"><h2 id="my-series-title">我的专栏</h2><button type="button" class="primary" :disabled="busy" @click="create">新建专栏</button></div>
    <form class="series-search" @submit.prevent="load()"><label class="sr-only" for="series-query">查找专栏</label><input id="series-query" v-model="query" type="search" maxlength="64" placeholder="查找专栏"><button :disabled="loading">搜索</button></form>
    <p v-if="loading&&!items.length" class="muted" role="status">正在载入专栏…</p>
    <div v-else-if="!items.length" class="series-empty"><h3>{{query?'没有找到专栏':'把文章写成一段连续的旅程'}}</h3><p>{{query?'换个关键词试试。':'创建专栏，再把已有文章按章节编排。文章仍可独立阅读。'}}</p></div>
    <div v-else class="series-table-wrap"><table class="series-table"><thead><tr><th>专栏</th><th>章节</th><th>状态</th></tr></thead><tbody><tr v-for="row in items" :key="row.id" :data-selected="selected?.id===row.id"><td><button type="button" class="series-row-title" :disabled="busy" @click="open(row)">{{row.title}}</button><small>{{date(row.updated_at)}}</small></td><td>{{row.total_chapter_count}}</td><td><span>{{row.status==='published'?'公开':'草稿'}}</span><small>{{row.state==='completed'?'已完结':'连载中'}}</small></td></tr></tbody></table></div>
    <button v-if="more" type="button" class="series-load-more" :disabled="loading" @click="load(true)">{{loading?'正在载入…':'更多专栏'}}</button>
   </section>
   <form v-if="selected" class="series-editor" @submit.prevent="save"><button type="button" class="quiet series-mobile-back" :disabled="busy" @click="back"><Icon name="arrow" :size="16"/>返回专栏列表</button><div class="series-panel-head"><div><h2>{{selected.id?'编辑专栏':'新建专栏'}}</h2><span class="muted">{{dirty?'有未保存的修改':'已保存'}}</span></div><button class="primary" :disabled="busy||!selected.title?.trim()||deletedChapters>0">{{busy?'处理中…':'保存专栏'}}</button></div>
    <fieldset :disabled="busy" class="series-fields"><label>专栏名称<input v-model="selected.title" required maxlength="120" placeholder="例如：从零搭建个人博客"></label><label>简介<textarea v-model="selected.description" maxlength="1200" rows="3" placeholder="这组连载讲什么，适合谁阅读"></textarea></label>
    <div class="series-choices"><SelectField v-model="selected.state" label="连载状态" :options="stateOptions" :disabled="busy"/><SelectField v-model="selected.status" label="可见范围" :options="visibilityOptions" :disabled="busy"/></div>
    <details class="series-advanced"><summary>专栏封面</summary><div class="series-cover-tools"><img v-if="selected.cover_media_id" :src="'/media/'+selected.cover_media_id" width="120" height="68" alt="专栏封面预览"><label class="button">上传封面<input class="sr-only" type="file" accept="image/png,image/jpeg,image/webp,image/gif" @change="upload"></label><button v-if="selected.cover_media_id" type="button" class="quiet" @click="selected.cover_media_id=null">移除封面</button></div></details>
    <div class="series-panel-head series-chapter-head"><div><h3>章节目录</h3><span class="muted">{{chapters.length}} / 300 章 · 未公开文章只在这里可见</span></div><button type="button" :aria-expanded="picker" aria-controls="series-post-picker" @click="showPicker">{{picker?'收起文章':'添加文章'}}</button></div>
    <div v-if="picker" id="series-post-picker" class="series-post-picker"><div class="series-search"><label class="sr-only" for="series-post-query">搜索我的文章</label><input id="series-post-query" v-model="postQuery" type="search" maxlength="64" placeholder="搜索我的文章" @keydown.enter.prevent="findPosts()"><button type="button" :disabled="postLoading" @click="findPosts()">搜索</button></div><p v-if="postLoading" role="status">正在查找文章…</p><ul v-else class="series-post-options"><li v-for="post in candidates" :key="post.id"><span>{{post.title||'未命名文章'}}</span><button type="button" :disabled="selectedIDs.has(String(post.id))||chapters.length>=300" @click="add(post)">{{selectedIDs.has(String(post.id))?'已加入':'加入'}}</button></li><li v-if="!candidates.length" class="muted">没有可添加的文章，先创建文章或换个关键词。</li></ul><button v-if="postMore" type="button" :disabled="postLoading" @click="findPosts(true)">继续查找</button></div>
    <p v-if="deletedChapters" class="notice error" role="alert">有 {{deletedChapters}} 篇文章已删除，请先从目录移除再保存。</p>
    <ol v-if="chapters.length" class="series-chapter-editor"><li v-for="(chapter,index) in chapters" :key="chapter.post_id||chapter.id"><span class="series-chapter-number">{{index+1}}</span><div class="series-chapter-name"><strong>{{chapter.title||'未命名文章'}}</strong><small>{{chapter.status==='deleted'?'文章已删除 · 请移除':chapter.status==='published'?'已公开':'未公开 · 读者暂不可见'}}</small></div><div class="series-chapter-actions"><button type="button" class="quiet" :disabled="index===0" :aria-label="'上移第'+(index+1)+'章'" @click="move(index,-1)"><Icon name="chevron" :size="16" class="series-move-up"/></button><button type="button" class="quiet" :disabled="index===chapters.length-1" :aria-label="'下移第'+(index+1)+'章'" @click="move(index,1)"><Icon name="chevron" :size="16"/></button><button type="button" class="quiet" :aria-label="'移除第'+(index+1)+'章'" @click="chapters.splice(index,1)">移除</button></div></li></ol><p v-else class="series-empty">还没有章节，添加文章后按阅读顺序编排。</p>
    </fieldset><div class="series-editor-footer"><a v-if="selected.id&&selected.status==='published'" :href="'/series/'+selected.id" target="_blank" rel="noopener">查看公开专栏</a><button v-if="selected.id" type="button" class="quiet danger" :disabled="busy" @click="remove">删除专栏</button></div>
   </form><section v-else class="series-editor-placeholder"><Icon name="posts" :size="28"/><h2>选择一个专栏开始编排</h2><p>将已有文章排列成章节，让读者顺着目录继续阅读。</p></section>
  </div>
 </section>
</template>
